"cat": "Yaratıcılık",
"type": "tweet",
"summary": "Kevin Kelly'nin '1.000 Gerçek Hayran' fikri: bir üreticinin geçinmesi için milyonlarca kitleye değil, ürettiği her şeyi alan yaklaşık bin sadık destekçiye ihtiyacı vardır. Kelly bu yazıyı güncelleyip fikrin bugün her zamankinden geçerli olduğunu söylüyor.",
"title": "",
"text": "I rewrote my 1,000 True Fans essay. Now valid more than ever. (This time the revision will stay up.) <a href=\"https://t.co/FZGJWutbyx\" target=\"_blank\" rel=\"noopener nofollow\">https://t.co/FZGJWutbyx</a>",
