"summary": "Büyük dil modelleriyle birlikte bilgisayara ne yapacağını söylemenin en güçlü yolu artık düz İngilizce (doğal dil). Programlamanın tanımının genişlediğini çarpıcı biçimde özetleyen bir gözlem.",
