"cat": "Yazılım",
"type": "tweet",
"summary": "Bilgisayar biliminde iki zor problem vardır: önbellek geçersizleştirme, isimlendirme ve bir-eksik (off-by-one) hataları. Şaka, Phil Karlton'ın ünlü sözüne üçüncü maddeyi ekleyerek kendi hatasını sergiliyor.",
