"title": "",
"text": "Create more value than you capture! That should be every entrepreneur&#x27;s aspiration. <a href=\"https://t.co/HwW6y1fd3H\" target=\"_blank\" rel=\"noopener nofollow\">https://t.co/HwW6y1fd3H</a>",
