"url": "https://x.com/martinfowler/status/96580123301650432",
"author": "Martin Fowler",
"handle": "@martinfowler",
"cat": "Yazılım",
"type": "tweet",
"summary": "Bir iş canını acıtıyorsa onu daha sık yap. Entegrasyon, dağıtım ya da test gibi sancılı işleri sık yaptıkça her seferinde küçülür, kolaylaşır ve otomasyona açılır.",
"title": "",
